function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const item = multisetDiff(before.item, after.item);
  const value_joined = multisetDiff(before.value_joined, after.value_joined);
  return {
    rels: [
      { rel: "item", add: item.add, del: item.del },
      { rel: "value_joined", add: value_joined.add, del: value_joined.del },
    ],
    carryPending: false,
  };
}

